#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <sstream>

template <typename T>
T add(T a, T b) {
    return a + b;
}

template <typename T>
class Calculator {
private:
    T val1, val2;
public:
    Calculator(T v1, T v2) : val1(v1), val2(v2) {}

    T multiply() {
        return val1 * val2;
    }

    T subtract() {
        return val1 - val2;
    }
};

int main() {
    std::string line;
    std::getline(std::cin, line);

    std::istringstream iss(line);
    std::string type;
    iss >> type;

    if (type == "int") {
        int a, b;
        iss >> a >> b;
        Calculator<int> calc(a, b);
        std::cout << "Addition: " << add(a, b) << std::endl;
        std::cout << "Subtraction: " << calc.subtract() << std::endl;
        std::cout << "Multiplication: " << calc.multiply() << std::endl;
    } else if (type == "double") {
        double a, b;
        iss >> a >> b;
        Calculator<double> calc(a, b);
        std::cout << "Addition: " << add(a, b) << std::endl;
        std::cout << "Subtraction: " << calc.subtract() << std::endl;
        std::cout << "Multiplication: " << calc.multiply() << std::endl;
    } else if (type == "string") {
        std::string a, b;
        iss >> a >> b;
        Calculator<std::string> calc(a, b);
        std::cout << "Addition: " << add(a, b) << std::endl;
        std::cout << "Subtraction: Not Supported" << std::endl;
        std::cout << "Multiplication: Not Supported" << std::endl;
    }

    return 0;
}
